/* Generated by scripts/build.mjs from the shared legal page terms.html. */
/* Theme: System, Light, Dark. Same storage key as the home page so the choice carries over. */
(function () {
  var THEMES = ['system', 'light', 'dark'];
  var theme = 'system';
  try { theme = localStorage.getItem('aa-theme') || 'system'; } catch (e) {}
  if (THEMES.indexOf(theme) < 0) theme = 'system';
  var label = document.getElementById('themeLabel');
  function apply() {
    if (theme === 'system') document.documentElement.removeAttribute('data-theme');
    else document.documentElement.setAttribute('data-theme', theme);
    label.textContent = theme.charAt(0).toUpperCase() + theme.slice(1);
  }
  document.getElementById('themeToggle').addEventListener('click', function () {
    theme = THEMES[(THEMES.indexOf(theme) + 1) % THEMES.length];
    try { localStorage.setItem('aa-theme', theme); } catch (e) {}
    apply();
  });
  apply();
})();
